// Example: building a simple index
function buildWordIndex(docs) {
  const index = {};
  for (const doc of docs) {
    const words = doc.text.split(' ');
    for (const word of words) {
      if (!index[word]) index[word] = [];
      index[word].push(doc.id);
    }
  }
  return index;
}

