// Example: A function that finds matching items
function findMatches(items, query) {
  const queryTerms = query.toLowerCase().split(' ');
  const matches = [];
  for (const item of items) {
    if (queryTerms.every(term => item.tags.includes(term))) {
      matches.push(item.id);
    }
  }
  return matches;
}

